shapes={'1':[(r,c) for r in range(2) for c in range(5)], '6':[(r,c) for r in range(6) for c in range(2)], '2':[(r,c) for r in range(2) for c in range(2)], '8a':[(0,c) for c in range(4)],'8b':[(0,c) for c in range(4)],'3':[(r,c) for r in range(3) for c in range(2)],'0':[(0,0)]}
# check exact cover enumerate preserving orientation then rotations

def orientations(coords, rotate=False):
    out=set()
    for k in range(4 if rotate else 1):
        pts=[]
        for r,c in coords:
            x,y=r,c
            for _ in range(k): x,y=y,-x
            pts.append((x,y))
        mr=min(x for x,y in pts); mc=min(y for x,y in pts)
        out.add(tuple(sorted((x-mr,y-mc) for x,y in pts)))
    return [list(o) for o in out]
def solve(rotate=False, maxsol=5):
    names=list(shapes)
    options={}
    for name,coords in shapes.items():
        plist=[]
        for orient in orientations(coords,rotate):
            h=max(r for r,c in orient)+1; w=max(c for r,c in orient)+1
            for r in range(15-h+1):
                for c in range(7-w+1):
                    cells=frozenset((r+x,c+y) for x,y in orient)
                    if cells<=holes: plist.append((cells,(name,r,c,orient)))
        options[name]=plist
    # treat 8a,b same
    remaining=set(names); sols=[]
    def rec(rem, uncovered, chosen):
        if len(sols)>=maxsol:return
        if not uncovered:
            if not rem: sols.append(chosen.copy())
            return
        # choose cell with few feasible placements counting rem pieces
        best=None; bopts=None
        for cell in uncovered:
            cand=[]
            for nm in rem:
                # dedup duplicate identical 8s not issue
                for cells,meta in options[nm]:
                    if cell in cells and cells<=uncovered: cand.append((cells,meta,nm))
            if bopts is None or len(cand)<len(bopts): best,bopts=cell,cand
            if len(cand)==0:return
        for cells,meta,nm in bopts:
            rec(rem-{nm},uncovered-cells,chosen+[meta])
    rec(remaining,holes,[])
    return sols
sol0=solve(False,3); print('no rotation',len(sol0)); print(sol0[:1])
